import React, { useState } from 'react';
import { MatrixInput } from './MatrixInput';
import { FileUpload } from './FileUpload';
import { ResultsDisplay } from './ResultsDisplay';
import { IterationTable } from './IterationTable';
import { Alert } from '../common/Alert';
import { Loader } from '../common/Loader';
import { lab1Api } from '../../services/api';
import { SolutionResponse, FileData } from '../../types';
import { Play, FileText, Keyboard, Download, Info } from 'lucide-react';
import toast from 'react-hot-toast';

export const SLAUPage: React.FC = () => {
    const [n, setN] = useState<number>(3);
    const [inputMode, setInputMode] = useState<'manual' | 'file'>('manual');
    const [matrix, setMatrix] = useState<number[][]>(
        Array(3).fill(0).map(() => Array(3).fill(0))
    );
    const [vector, setVector] = useState<number[]>(Array(3).fill(0));
    const [epsilon, setEpsilon] = useState<number>(0.0001);
    const [maxIterations, setMaxIterations] = useState<number>(1000);
    const [loading, setLoading] = useState<boolean>(false);
    const [result, setResult] = useState<SolutionResponse | null>(null);
    const [showExample, setShowExample] = useState<boolean>(false);

    const handleNChange = (newN: number) => {
        if (newN > 20) {
            toast.error('Максимальная размерность - 20');
            return;
        }
        if (newN < 1) {
            toast.error('Размерность должна быть положительной');
            return;
        }
        setN(newN);
        setMatrix(Array(newN).fill(0).map(() => Array(newN).fill(0)));
        setVector(Array(newN).fill(0));
        setResult(null);
    };

    const handleFileData = (data: FileData) => {
        setN(data.matrix.length);
        setMatrix(data.matrix);
        setVector(data.vector);
        setResult(null);
        toast.success('Матрица загружена из файла');
    };

    const handleSolve = async () => {
        // Валидация
        for (let i = 0; i < n; i++) {
            if (Math.abs(matrix[i][i]) < 1e-10) {
                toast.error(`Нулевой диагональный элемент в строке ${i + 1}`);
                return;
            }
        }

        setLoading(true);
        try {
            const response = await lab1Api.solve({
                matrix,
                vector,
                params: {
                    epsilon,
                    maxIterations
                }
            });

            setResult(response.data);

            if (response.data.status === 'success') {
                toast.success(response.data.message);
            } else {
                toast.error(response.data.message);
            }
        } catch (error: any) {
            toast.error(error.message || 'Ошибка при решении СЛАУ');
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const loadExample = () => {
        // Пример из лекции (с диагональным преобладанием)
        const exampleMatrix = [
            [10, 1, 1],
            [2, 10, 1],
            [2, 2, 10]
        ];
        const exampleVector = [12, 13, 14];

        setN(3);
        setMatrix(exampleMatrix);
        setVector(exampleVector);
        setEpsilon(0.0001);
        setResult(null);
        toast.success('Загружен пример из методички');
    };

    return (
        <div className="container mx-auto px-4 py-8 max-w-7xl">
            {/* Шапка */}
            <div className="mb-8">
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900 mb-2">
                            Лабораторная работа №1
                        </h1>
                        <p className="text-lg text-gray-600">
                            Решение систем линейных алгебраических уравнений
                        </p>
                    </div>
                    <div className="px-4 py-2 bg-blue-100 text-blue-800 rounded-full text-sm font-medium">
                        Метод Гаусса-Зейделя (Вариант 20)
                    </div>
                </div>

                {/* Кнопка примера */}
                <button
                    onClick={loadExample}
                    className="mt-4 flex items-center gap-2 text-sm text-blue-600 hover:text-blue-800"
                >
                    <Download className="w-4 h-4" />
                    Загрузить пример из методички
                </button>
            </div>

            {/* Основной контент */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Левая колонка - ввод данных */}
                <div className="space-y-6">
                    <div className="card">
                        <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
                            <Keyboard className="w-5 h-5 text-gray-500" />
                            Ввод данных
                        </h2>

                        {/* Размерность */}
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Размерность системы (n ≤ 20)
                            </label>
                            <input
                                type="number"
                                min="1"
                                max="20"
                                value={n}
                                onChange={(e) => handleNChange(parseInt(e.target.value) || 1)}
                                className="input w-24"
                            />
                        </div>

                        {/* Режим ввода */}
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Способ ввода
                            </label>
                            <div className="flex gap-3">
                                <button
                                    onClick={() => setInputMode('manual')}
                                    className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors ${
                                        inputMode === 'manual'
                                            ? 'bg-blue-600 text-white'
                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                    }`}
                                >
                                    <Keyboard className="w-4 h-4" />
                                    Ручной ввод
                                </button>
                                <button
                                    onClick={() => setInputMode('file')}
                                    className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors ${
                                        inputMode === 'file'
                                            ? 'bg-blue-600 text-white'
                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                    }`}
                                >
                                    <FileText className="w-4 h-4" />
                                    Из файла
                                </button>
                            </div>
                        </div>

                        {/* Ввод данных */}
                        {inputMode === 'manual' ? (
                            <MatrixInput
                                n={n}
                                matrix={matrix}
                                vector={vector}
                                onChange={(newMatrix, newVector) => {
                                    setMatrix(newMatrix);
                                    setVector(newVector);
                                    setResult(null);
                                }}
                            />
                        ) : (
                            <FileUpload onDataLoaded={handleFileData} />
                        )}

                        {/* Параметры метода */}
                        <div className="mt-6 grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Точность (ε)
                                </label>
                                <input
                                    type="number"
                                    min="1e-10"
                                    max="1"
                                    step="1e-6"
                                    value={epsilon}
                                    onChange={(e) => setEpsilon(parseFloat(e.target.value))}
                                    className="input"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Макс. итераций
                                </label>
                                <input
                                    type="number"
                                    min="1"
                                    max="10000"
                                    value={maxIterations}
                                    onChange={(e) => setMaxIterations(parseInt(e.target.value))}
                                    className="input"
                                />
                            </div>
                        </div>

                        {/* Кнопка решения */}
                        <button
                            onClick={handleSolve}
                            disabled={loading}
                            className="mt-6 w-full btn-success flex items-center justify-center gap-2 py-3"
                        >
                            {loading ? (
                                <>
                                    <Loader />
                                    <span>Решение...</span>
                                </>
                            ) : (
                                <>
                                    <Play className="w-5 h-5" />
                                    Решить систему
                                </>
                            )}
                        </button>
                    </div>

                    {/* Информация о формате файла */}
                    {inputMode === 'file' && (
                        <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                            <div className="flex items-start gap-2">
                                <Info className="w-5 h-5 text-blue-600 mt-0.5 flex-shrink-0" />
                                <div>
                                    <h4 className="font-medium text-blue-800 mb-1">
                                        Формат файла:
                                    </h4>
                                    <p className="text-sm text-blue-700 mb-2">
                                        Первая строка - размерность n, затем n строк по n+1 чисел
                                        (коэффициенты и правая часть)
                                    </p>
                                    <pre className="text-xs bg-white p-3 rounded border border-blue-200 overflow-x-auto">
{`3
2 1 -1 8
-3 -1 2 -11
-2 1 2 -3`}
                                    </pre>
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Правая колонка - результаты */}
                <div className="space-y-6">
                    {result ? (
                        <div className="card">
                            <h2 className="text-xl font-semibold mb-4">Результаты</h2>

                            {result.status === 'error' ? (
                                <Alert type="error" message={result.message} />
                            ) : (
                                <>
                                    <ResultsDisplay result={result} />

                                    {result.iterationHistory && result.iterationHistory.length > 0 && (
                                        <div className="mt-6">
                                            <h3 className="text-lg font-medium mb-3">
                                                История итераций
                                            </h3>
                                            <IterationTable
                                                history={result.iterationHistory}
                                                solution={result.solution}
                                            />
                                        </div>
                                    )}
                                </>
                            )}
                        </div>
                    ) : (
                        <div className="card flex flex-col items-center justify-center text-center py-12 text-gray-500">
                            <Play className="w-12 h-12 mb-3 text-gray-400" />
                            <p className="text-lg">Введите данные и нажмите "Решить"</p>
                            <p className="text-sm mt-2">Будут отображены результаты решения</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};
